source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v)
    frames = []
    for color, count in counts.items():
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                     if r in (r0, r1) or c in (c0, c1)}
        if len(cells) == len(perimeter) and set(cells) == perimeter:
            frames.append((color, r0, r1, c0, c1))
    out = [[0]*w for _ in range(h)]
    frame_colors = {f[0] for f in frames}
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
        need = sum(1 for r in range(r0+1, r1) for c in range(c0+1, c1)
                   if (r-r0-1 + c-c0-1) % 2 == 0)
        matches = [v for v,n in counts.items() if v not in frame_colors and n == need]
        if matches:
            fill = matches[0]
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if (r-r0-1 + c-c0-1) % 2 == 0:
                        out[r][c] = fill
    return out
'''
